// The backdrop — INDEX1 · KR 700 PA
//
// One field behind everything, fixed to the viewport, dimmed. Ported from a
// React component generated by the 21st.dev Shader Builder ("Mesh drift"); this
// project is Vite and vanilla JS, so it is the same shader rebuilt in the stack
// that is here. The GLSL is verbatim — it is generated output and re-typing it
// by hand is how a generated artefact silently stops matching its source.
//
// WHAT THE PORT CHANGED, AND WHY
//
//   IT SHARES THE PAGE'S TICKER. The source ran its own requestAnimationFrame.
//   There is already a loop on this page driving a WebGL renderer, and two
//   independent rAF loops both submitting draw calls contend for the same frame
//   — the symptom is not a dropped frame, it is a frame that lands late and
//   makes the SCROLL feel loose, which is the one thing this page cannot afford.
//   So it renders from gsap.ticker, in the same frame as the scene.
//
//   THE BRIGHTNESS IS DIMMED AT THE PALETTE. Not with a CSS filter, which would
//   cost a full-screen composite pass every frame, and not with the shader's own
//   u_brightness, which SUBTRACTS and therefore crushes the dark end to black
//   while barely touching the light end — that is a contrast change wearing the
//   name of a brightness change. Scaling the colour uniforms is multiplicative:
//   it holds every relationship inside the mesh and only lowers the level.
//
//   IT STOPS WHEN NOTHING CAN SEE IT. Kept from the source, because it is right:
//   hidden tab, or scrolled out of view, and it stops submitting frames.
//
//   REDUCED MOTION GETS ONE FRAME. The field is drawn once and then held. A
//   still field is a composition; an absent one is a hole where the art
//   direction was (MJ9).
//
//   IT ANSWERS THE SCROLL. The field is fixed to the viewport, so without this
//   it would be the one element on the page that never acknowledges the journey
//   — 805vh of travel over a picture that does not know it happened. The scroll
//   drives u_offset, which PANS the field rather than moving the element: the
//   layer stays put and the world inside it goes past, which is what a
//   background at depth does. It is scrubbed, so the visitor keeps the transport
//   (MJ6) and every stopped position is a composed frame (MJ4).
//
// WHERE IT SITS. Below the scene's own canvas, which is transparent, so the
// stack reads: backdrop, the opening's type once it has receded, the machine,
// the page. One background for the whole page, and it does not scroll away.

const VERT = `attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}`;

const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec3 u_colors[8];
uniform vec4 u_scene;      // resolution.xy, time, colour count
uniform vec4 u_shape;      // scale, intensity, paramA, warp
uniform vec4 u_surface;    // detail, contrast, brightness, saturation
uniform vec4 u_finish;     // hue, vignette, blur, grain
uniform vec4 u_transform;  // seed, rotation, drift, OKLab toggle
uniform vec4 u_space;      // offset.xy, pointer.xy
uniform vec4 u_cursor;

#define u_resolution u_scene.xy
#define u_time u_scene.z
#define u_colorCount u_scene.w
#define u_scale u_shape.x
#define u_intensity u_shape.y
#define u_paramA u_shape.z
#define u_warp u_shape.w
#define u_detail u_surface.x
#define u_contrast u_surface.y
#define u_brightness u_surface.z
#define u_saturation u_surface.w
#define u_hue u_finish.x
#define u_vignette u_finish.y
#define u_blur u_finish.z
#define u_grain u_finish.w
#ifdef GL_FRAGMENT_PRECISION_HIGH
#define u_seed u_transform.x
#else
#define u_seed mod(u_transform.x, 31.0)
#endif
#define u_rotate u_transform.y
#define u_drift u_transform.z
#define u_oklab u_transform.w
#define u_offset u_space.xy
#define u_mouse u_space.zw
#define u_cursorPresence u_cursor.x
#define u_cursorEffect u_cursor.y
#define u_cursorStrength u_cursor.z
#define u_cursorRadius u_cursor.w

float hash21(vec2 p) {
#ifndef GL_FRAGMENT_PRECISION_HIGH
  p = mod(p, 31.0);
#endif
  p = fract(p * vec2(234.34, 435.345));
  p += dot(p, p + 34.23);
  return fract(p.x * p.y);
}

float grainHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
#ifndef GL_FRAGMENT_PRECISION_HIGH
  p = mod(p, 31.0);
#endif
  float n = sin(dot(p, vec2(41.0, 289.0)));
  return fract(vec2(15731.743, 7892.321) * n);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash21(i), hash21(i + vec2(1.0, 0.0)), u.x),
    mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), u.x),
    u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = p * 2.03 + vec2(17.0, 9.2);
    a *= 0.5;
  }
  return v;
}

vec3 srgbToLinear(vec3 c) {
  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)),
    step(0.04045, c));
}
vec3 linearToSrgb(vec3 c) {
  return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055,
    step(0.0031308, c));
}
vec3 linToOklab(vec3 c) {
  float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
  float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
  float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
  l = pow(max(l, 0.0), 1.0 / 3.0);
  m = pow(max(m, 0.0), 1.0 / 3.0);
  s = pow(max(s, 0.0), 1.0 / 3.0);
  return vec3(
    0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
vec3 oklabToLin(vec3 c) {
  float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
  float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
  float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
  l = l * l * l; m = m * m * m; s = s * s * s;
  return vec3(
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}
vec3 mixColour(vec3 a, vec3 b, float t) {
  if (u_oklab > 0.5) {
    vec3 la = linToOklab(srgbToLinear(a));
    vec3 lb = linToOklab(srgbToLinear(b));
    return clamp(linearToSrgb(oklabToLin(mix(la, lb, t))), 0.0, 1.0);
  }
  return mix(a, b, t);
}

vec3 palette(float x) {
  float n = max(u_colorCount - 1.0, 1.0);
  float f = clamp(x, 0.0, 1.0) * n;
  vec3 col = u_colors[0];
  for (int i = 0; i < 7; i++) {
    if (float(i) < n)
      col = mixColour(col, u_colors[i + 1],
        smoothstep(0.0, 1.0, clamp(f - float(i), 0.0, 1.0)));
  }
  return col;
}

vec3 hueRotate(vec3 col, float a) {
  const mat3 toYIQ = mat3(0.299, 0.596, 0.211,
                          0.587, -0.274, -0.523,
                          0.114, -0.322, 0.312);
  const mat3 toRGB = mat3(1.0, 1.0, 1.0,
                          0.956, -0.272, -1.106,
                          0.621, -0.647, 1.703);
  vec3 yiq = toYIQ * col;
  float ca = cos(a), sa = sin(a);
  yiq = vec3(yiq.x, yiq.y * ca - yiq.z * sa, yiq.y * sa + yiq.z * ca);
  return toRGB * yiq;
}

vec3 shade(vec2 uv, vec2 p, float t) {
  vec3 acc = u_colors[0] * 0.15;
  float total = 0.15;
  for (int i = 0; i < 8; i++) {
    if (float(i) >= u_colorCount) break;
    float fi = float(i);
    vec2 c = vec2(
      sin(t * (0.21 + fi * 0.071) + fi * 2.4 + u_seed),
      cos(t * (0.17 + fi * 0.093) + fi * 1.7)) * (0.45 + u_intensity * 0.35);
    float w = exp(-dot(p - c, p - c) * 6.0);
    acc += u_colors[i] * w;
    total += w;
  }
  return acc / total;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  vec2 screenUv = uv;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution.xy)
    / min(u_resolution.x, u_resolution.y);
  float cursorMask = 0.0;

  uv = p * min(u_resolution.x, u_resolution.y) / u_resolution.xy + 0.5;
  p *= u_scale;
  if (abs(u_rotate) > 0.0001) {
    float cr = cos(u_rotate), sr = sin(u_rotate);
    p = mat2(cr, -sr, sr, cr) * p;
  }
  p += u_offset;
  if (u_drift > 0.0001)
    p += u_drift * vec2(sin(u_time * 0.31), cos(u_time * 0.23));
  if (u_warp > 0.0) {
    p += u_warp * (vec2(
      fbm(p * u_detail + u_seed),
      fbm(p * u_detail + vec2(5.2, 1.3))) - 0.5);
  }
  vec3 col;
  if (u_blur > 0.0) {
    float e = u_blur;
    float pe = e * u_scale;
    vec2 uvE = vec2(e) * min(u_resolution.x, u_resolution.y) / u_resolution.xy;
    col  = shade(uv, p, u_time) * 0.36;
    col += shade(uv + vec2(uvE.x, 0.0), p + vec2(pe, 0.0), u_time) * 0.16;
    col += shade(uv - vec2(uvE.x, 0.0), p - vec2(pe, 0.0), u_time) * 0.16;
    col += shade(uv + vec2(0.0, uvE.y), p + vec2(0.0, pe), u_time) * 0.16;
    col += shade(uv - vec2(0.0, uvE.y), p - vec2(0.0, pe), u_time) * 0.16;
  } else {
    col = shade(uv, p, u_time);
  }
  if (abs(u_contrast - 1.0) > 0.0001)
    col = (col - 0.5) * u_contrast + 0.5;
  if (abs(u_saturation - 1.0) > 0.0001) {
    float luma = dot(col, vec3(0.299, 0.587, 0.114));
    col = mix(vec3(luma), col, u_saturation);
  }
  if (abs(u_hue) > 0.0001)
    col = hueRotate(col, u_hue);
  if (abs(u_brightness) > 0.0001)
    col += u_brightness;
  if (u_vignette > 0.0001) {
    float vd = length(screenUv - 0.5) * 1.41421356;
    col *= 1.0 - u_vignette * smoothstep(0.35, 1.0, vd);
  }
  if (u_grain > 0.0001)
    col += (grainHash(
      gl_FragCoord.xy + vec2(u_seed * 17.0, u_seed * 31.0)) - 0.5) * u_grain;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
`;

/*
  THE DIM.

  The one number that was asked for, kept as one number. It scales the palette,
  which is a multiplicative brightness: every relationship inside the mesh is
  held and only the level moves. The generated recipe is a teal/mint/sand field
  built for a bright page; at full strength it would be the loudest thing on a
  page whose ground is #0a0c0d and whose only colour is the machine's own paint.
  At 0.26 it is a field the machine sits in rather than a picture behind it.
*/
const DIM = 0.5;

/*
  THE PALETTE — dirty blue and dirty green.

  The generated recipe shipped teal, mint and sand: a bright field built for a
  bright page, and three hues where this page has one. Replaced with two dirty
  neutrals and the ground they sit on. "Dirty" is the operative word and it is a
  saturation instruction, not a hue one — these are desaturated and slightly
  green-shifted, so the field reads as a room with air in it rather than as a
  colour anybody chose.

  They also have a job. The machine's paint is orange; the ground is a
  blue-green near-black already, chosen because a neutral black made the steel
  read purple against the cool key. Blue and green are the complement side of
  that orange, so the field pushes the machine forward instead of arguing with
  it, and it does it in the colour the ground was already in.

    #070a0c  the hall, all but black — the anchor, and most of the frame
    #23384c  dirty blue, cool and low
    #2c3f33  dirty green, the same value, warmer
    #3b5257  where the two meet and lift, and the brightest thing in the field
*/
const UNIFORMS = {
  colors: [
    [0.02745, 0.03922, 0.04706],
    [0.13725, 0.21961, 0.29804],
    [0.17255, 0.24706, 0.20000],
    [0.23137, 0.32157, 0.34118],
    [0.23137, 0.32157, 0.34118],
    [0.23137, 0.32157, 0.34118],
    [0.23137, 0.32157, 0.34118],
    [0.23137, 0.32157, 0.34118],
  ],
  colorCount: 4,
  scale: 2.0,
  intensity: 0.54,
  paramA: 0.47,
  warp: 0.042,
  detail: 1.536,
  contrast: 1.158,
  brightness: 0.0,
  saturation: 1.0,
  hue: 0.0,
  vignette: 0.21,
  blur: 0.002,
  grain: 0.101,
  seed: 4012.0,
  rotate: 5.6549,
  offsetX: 0.11,
  offsetY: -0.19,
  drift: 0.116,
  cursorEffect: 2.0,
  cursorStrength: 0.65,
  cursorRadius: 0.46,
  oklab: 0.0,
  timeScale: -0.727,
};

/**
 * @param {HTMLCanvasElement} canvas
 * @param {{ ticker: any, reduced?: boolean }} options
 * @returns {{ dispose(): void } | null} null when WebGL is unavailable — the
 *   page's ground is already the right colour underneath, so there is nothing
 *   to apologise for and nothing to draw in its place.
 */
export function createBackdrop(canvas, { ticker, reduced = false } = {}) {
  const gl = canvas.getContext('webgl', { antialias: false });
  if (!gl) return null;

  const compile = (type, src) => {
    const s = gl.createShader(type);
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      console.warn('[backdrop] shader did not compile', gl.getShaderInfoLog(s));
    }
    return s;
  };

  const program = gl.createProgram();
  const vs = compile(gl.VERTEX_SHADER, VERT);
  const fs = compile(gl.FRAGMENT_SHADER, FRAG);
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  gl.useProgram(program);

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, 'a_position');
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  const uni = {
    colors: gl.getUniformLocation(program, 'u_colors'),
    scene: gl.getUniformLocation(program, 'u_scene'),
    shape: gl.getUniformLocation(program, 'u_shape'),
    surface: gl.getUniformLocation(program, 'u_surface'),
    finish: gl.getUniformLocation(program, 'u_finish'),
    transform: gl.getUniformLocation(program, 'u_transform'),
    space: gl.getUniformLocation(program, 'u_space'),
    cursor: gl.getUniformLocation(program, 'u_cursor'),
  };

  gl.uniform3fv(uni.colors, new Float32Array(UNIFORMS.colors.flat().map((c) => c * DIM)));
  gl.uniform4f(uni.shape, UNIFORMS.scale, UNIFORMS.intensity, UNIFORMS.paramA, UNIFORMS.warp);
  gl.uniform4f(uni.surface, UNIFORMS.detail, UNIFORMS.contrast, UNIFORMS.brightness, UNIFORMS.saturation);
  gl.uniform4f(uni.finish, UNIFORMS.hue, UNIFORMS.vignette, UNIFORMS.blur, UNIFORMS.grain);
  gl.uniform4f(uni.transform, UNIFORMS.seed, UNIFORMS.rotate, UNIFORMS.drift, UNIFORMS.oklab);
  // The cursor field is left at zero presence. The recipe had it disabled, and a
  // pointer-reactive background under a page that is already reading the pointer
  // for scroll is a second input story nobody asked for.
  gl.uniform4f(uni.cursor, 0, UNIFORMS.cursorEffect, UNIFORMS.cursorStrength, UNIFORMS.cursorRadius);

  /*
    How far the field pans across the whole page. Authored, and the two axes are
    deliberately unequal: an equal pan reads as the layer sliding, and a field at
    depth should look like it is being travelled through rather than dragged.
    Small numbers — u_scale is 2.0, so 1.15 here is over half a field width.
  */
  const TRAVEL_X = -0.34;
  const TRAVEL_Y = 1.15;

  const start = performance.now();
  let scroll = 0;
  let visible = document.visibilityState === 'visible';
  let inView = true;
  let drawn = false;

  const resize = () => {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rawW = Math.max(1, Math.round(rect.width * dpr));
    const rawH = Math.max(1, Math.round(rect.height * dpr));
    // A hard pixel ceiling, kept from the source. This is a full-screen fbm and
    // the cost is per fragment; on a 4K display at dpr 2 it would be drawing
    // 33M fragments a frame behind a scene that also wants the GPU.
    const fit = Math.min(1, Math.sqrt(2_000_000 / Math.max(1, rawW * rawH)));
    const w = Math.max(1, Math.round(rawW * fit));
    const h = Math.max(1, Math.round(rawH * fit));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
      drawn = false;
    }
  };
  resize();

  const draw = (now) => {
    resize();
    const t = reduced ? 0 : ((now - start) / 1000) * UNIFORMS.timeScale;
    gl.uniform4f(uni.scene, canvas.width, canvas.height, t, UNIFORMS.colorCount);
    gl.uniform4f(
      uni.space,
      UNIFORMS.offsetX + scroll * TRAVEL_X,
      UNIFORMS.offsetY + scroll * TRAVEL_Y,
      0, 0,
    );
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    drawn = true;
  };

  const frame = () => {
    if (!visible || !inView) return;
    // Reduced motion gets one composed frame and then holds it. A resize
    // invalidates it, which is why `drawn` is cleared there rather than here.
    if (reduced && drawn) return;
    draw(performance.now());
  };

  ticker.add(frame);

  const io = new IntersectionObserver(([entry]) => {
    inView = entry?.isIntersecting ?? true;
    if (inView) drawn = false;
  });
  io.observe(canvas);

  const ro = new ResizeObserver(() => { drawn = false; resize(); });
  ro.observe(canvas);

  const onVisibility = () => {
    visible = document.visibilityState === 'visible';
    if (visible) drawn = false;
  };
  document.addEventListener('visibilitychange', onVisibility);

  return {
    /**
     * 0..1 down the page. Under reduced motion the field is a single composed
     * still and stays one — a scroll-linked pan is user-driven, but it is still
     * a moving picture, and the reduced path asked for a picture that does not.
     */
    setScroll(p) {
      if (reduced) return;
      const next = Math.min(Math.max(p, 0), 1);
      if (Math.abs(next - scroll) < 0.0005) return;
      scroll = next;
    },

    dispose() {
      ticker.remove(frame);
      io.disconnect();
      ro.disconnect();
      document.removeEventListener('visibilitychange', onVisibility);
      gl.deleteBuffer(buffer);
      gl.deleteProgram(program);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}
